import { useCallback, useEffect, useState, type ReactNode } from 'react';
import {
  AlertTriangle, BadgeCheck, Banknote, BusFront, Camera,
  CircleDollarSign, FileWarning, Landmark, Loader2, Plus, RefreshCw,
  Route, ScanLine, Search, Settings2, ShieldAlert, WalletCards, X,
} from 'lucide-react';
import { api } from '@/lib/api';
import { usePwaManifest } from '@/hooks/usePwaManifest';
import { InstallPwaButton } from '@/mobile/InstallPwaButton';

type Compliance = 'PAID' | 'DUE_SOON' | 'GRACE_PERIOD' | 'OVERDUE' | 'EXEMPT' | 'SUSPENDED';
interface Operator { id: string; name: string; phone: string; region: string; registrationNumber: string }
interface Plate { id: string; plateNumber: string; normalizedPlate: string }
interface Bus { id: string; operatorId: string; name: string; complianceStatus: Compliance; paidThrough?: string | null; currentLocation: string; plate: Plate | null; operator: Operator | null }
interface Policy { id: string; feeAmount: number | string; currency: string; periodDays: number; graceDays: number; dueSoonDays: number; governmentPercent: number | string; kobePercent: number | string; automaticAnprThreshold: number }
interface Payment { id: string; paymentReference: string; receiptNumber: string; amount: number | string; method: string; busCount: number; createdAt: string }
interface Alert { id: string; message: string; status: string; createdAt: string }
interface Detection { id: string; observedPlate: string; confidence: number; reviewStatus: string; complianceStatus: string; direction: string; detectedAt: string; imageUrl?: string }
interface Settlement { id: string; settlementReference: string; governmentAmount: number | string; grossAmount: number | string; status: string; paymentReference: string; periodStart: string; periodEnd: string }
interface CameraRow { id: string; code: string; name: string; location: string; confidenceThreshold: number }
interface RouteRow { id: string; code: string; name: string; origin: string; destination: string }
interface Trip { id: string; tripCode: string; origin: string; destination: string; scheduledDeparture: string; status: string; currentCheckpoint: string; eta?: string | null }
interface CaseRow { id: string; busId: string; status: string; reason?: string; explanation?: string; authority?: string; createdAt: string }
interface Metrics {
  registeredBuses: number; paid: number; dueSoon: number; gracePeriod: number; overdue: number; exempt: number; suspended: number;
  weeklyExpected: number; grossCollected: number; governmentAccrued: number; kobeRevenue: number; governmentOutstanding: number; openAlerts: number; manualReview: number;
}
interface Dashboard {
  ownerId: string; policy: Policy; operators: Operator[]; buses: Bus[]; metrics: Metrics;
  recentPayments: Payment[]; recentAlerts: Alert[]; recentDetections: Detection[]; settlements: Settlement[];
}

type Tab = 'overview' | 'fleet' | 'payments' | 'anpr' | 'government' | 'cases';
const money = (value: number | string | undefined, currency = 'TZS') => `${currency} ${Number(value || 0).toLocaleString(undefined, { maximumFractionDigits: 2 })}`;
const date = (value?: string | null) => value ? new Date(value).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }) : '—';
export default function KobeTransit() {
  const [tab, setTab] = useState<Tab>('overview');
  const [dashboard, setDashboard] = useState<Dashboard | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  usePwaManifest({ name: 'KobeOS Transit', shortName: 'Kobe Transit', startUrl: '/transit', iconBase: '/kobe-transit', themeColor: '#081b31', enabled: typeof window !== 'undefined' && window.location.pathname.startsWith('/transit') });

  const load = useCallback(async () => {
    setLoading(true); setError('');
    try {
      const value = await api<Dashboard>('/transit/dashboard', { offlineFallback: false });
      if (!value || !value.metrics || !value.policy) throw new Error('Transit dashboard returned an invalid response');
      setDashboard(value);
    } catch (cause) { setError((cause as Error).message || 'Could not load Transit'); }
    finally { setLoading(false); }
  }, []);
  useEffect(() => { void load(); }, [load]);

  const tabs: Array<{ key: Tab; label: string; icon: typeof BusFront; count?: number }> = [
    { key: 'overview', label: 'Overview', icon: BusFront },
    { key: 'fleet', label: 'Fleet & Trips', icon: Route },
    { key: 'payments', label: 'Plate Fees', icon: WalletCards },
    { key: 'anpr', label: 'ANPR', icon: ScanLine, count: dashboard?.metrics.manualReview },
    { key: 'government', label: 'Government', icon: Landmark, count: dashboard?.metrics.openAlerts },
    { key: 'cases', label: 'Exemptions & Disputes', icon: FileWarning },
  ];

  return (
    <div className="h-full min-h-0 flex flex-col bg-[#f4f7fb] text-slate-900 overflow-hidden" data-surface="light" data-module="kobe-transit">
      <header className="shrink-0 bg-[#081b31] text-white border-b border-white/10">
        <div className="h-16 px-4 sm:px-6 flex items-center justify-between gap-4">
          <div className="flex items-center gap-3 min-w-0">
            <div className="h-10 w-10 rounded-xl bg-cyan-400 text-[#081b31] grid place-items-center shadow-lg shadow-cyan-500/20"><BusFront className="h-5 w-5" /></div>
            <div className="min-w-0"><h1 className="font-black tracking-tight truncate">KobeOS Transit</h1><p className="text-[11px] text-cyan-100/70 truncate">Tracking · weekly compliance · government settlement</p></div>
          </div>
          <div className="flex items-center gap-2"><InstallPwaButton /><button onClick={() => void load()} disabled={loading} className="h-9 w-9 rounded-lg border border-white/15 grid place-items-center hover:bg-white/10 disabled:opacity-50" title="Refresh"><RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} /></button></div>
        </div>
        <nav className="px-2 sm:px-5 flex overflow-x-auto [scrollbar-width:none]">
          {tabs.map(({ key, label, icon: Icon, count }) => <button key={key} onClick={() => setTab(key)} className={`relative h-11 px-3 shrink-0 inline-flex items-center gap-2 text-xs font-bold border-b-2 ${tab === key ? 'text-cyan-300 border-cyan-300' : 'text-white/60 border-transparent hover:text-white'}`}><Icon className="h-4 w-4" />{label}{Boolean(count) && <span className="min-w-5 h-5 px-1 rounded-full bg-rose-500 text-white text-[10px] grid place-items-center">{count}</span>}</button>)}
        </nav>
      </header>
      <main className="flex-1 min-h-0 overflow-y-auto overscroll-contain">
        {loading && !dashboard ? <Loading /> : error && !dashboard ? <ErrorState message={error} retry={load} /> : dashboard ? (
          <div className="p-3 sm:p-6 max-w-[1440px] mx-auto">
            {error && <Notice tone="error">{error}</Notice>}
            {tab === 'overview' && <Overview data={dashboard} />}
            {tab === 'fleet' && <Fleet data={dashboard} reload={load} />}
            {tab === 'payments' && <Payments data={dashboard} reload={load} />}
            {tab === 'anpr' && <Anpr data={dashboard} reload={load} />}
            {tab === 'government' && <Government data={dashboard} reload={load} />}
            {tab === 'cases' && <Cases data={dashboard} reload={load} />}
          </div>
        ) : null}
      </main>
    </div>
  );
}

function Overview({ data }: { data: Dashboard }) {
  const m = data.metrics;
  return <div className="space-y-5">
    <section className="rounded-3xl bg-gradient-to-br from-[#0b2947] via-[#0c3558] to-[#075f72] text-white p-5 sm:p-7 overflow-hidden relative">
      <div className="absolute -right-14 -top-14 w-56 h-56 rounded-full bg-cyan-300/10" />
      <div className="relative grid lg:grid-cols-[1.3fr_.7fr] gap-6 items-end">
        <div><div className="inline-flex items-center gap-2 rounded-full bg-cyan-300/10 border border-cyan-200/20 px-3 py-1 text-[11px] font-bold text-cyan-200"><BadgeCheck className="h-3.5 w-3.5" /> POLICY ACTIVE</div><h2 className="mt-4 text-2xl sm:text-4xl font-black tracking-tight">Every bus. One plate history.<br className="hidden sm:block" /> One verified compliance record.</h2><p className="mt-3 text-sm text-white/65 max-w-2xl">ANPR sightings update trip location and check the same plate-level fee ledger. Enforcement alerts record compliance only; they do not invent fines or police actions.</p></div>
        <div className="rounded-2xl bg-white/10 border border-white/15 p-4"><div className="text-[11px] uppercase tracking-widest text-cyan-100/70">Current fee policy</div><div className="text-3xl font-black mt-1">{money(data.policy.feeAmount, data.policy.currency)}</div><div className="text-xs text-white/60 mt-1">Every {data.policy.periodDays} days · {data.policy.graceDays}-day grace</div><div className="mt-4 flex gap-2 text-xs"><span className="flex-1 rounded-lg bg-white/10 p-2">Government <b className="block text-base">{Number(data.policy.governmentPercent)}%</b></span><span className="flex-1 rounded-lg bg-white/10 p-2">Kobe <b className="block text-base">{Number(data.policy.kobePercent)}%</b></span></div></div>
      </div>
    </section>
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
      <Metric label="Registered buses" value={m.registeredBuses} icon={<BusFront />} />
      <Metric label="Paid / current" value={m.paid} sub={`${m.dueSoon} due soon`} tone="green" icon={<BadgeCheck />} />
      <Metric label="Overdue" value={m.overdue} sub={`${m.gracePeriod} in grace`} tone="red" icon={<ShieldAlert />} />
      <Metric label="Open camera alerts" value={m.openAlerts} sub={`${m.manualReview} scans to review`} tone="amber" icon={<Camera />} />
    </div>
    <div className="flex justify-end"><a href={`/transit-board/${data.ownerId}`} target="_blank" rel="noreferrer" className="h-9 px-3 rounded-xl bg-white border border-slate-200 inline-flex items-center gap-2 text-xs font-black text-slate-700"><BusFront className="h-4 w-4" /> Open public Transit Board</a></div>
    <div className="grid xl:grid-cols-[1.35fr_.65fr] gap-5">
      <Panel title="Plate compliance" subtitle={`${money(m.weeklyExpected, data.policy.currency)} expected per cycle`}>
        {!data.buses.length ? <Empty title="No buses registered" body="Open Fleet & Trips to add an operator and the first bus." /> : <div className="divide-y divide-slate-100">{data.buses.map((bus) => <div key={bus.id} className="py-3 flex items-center gap-3"><div className="h-10 w-10 rounded-xl bg-slate-100 grid place-items-center"><BusFront className="h-5 w-5 text-slate-600" /></div><div className="min-w-0 flex-1"><div className="font-bold truncate">{bus.name} <span className="font-mono text-xs text-slate-500">{bus.plate?.plateNumber}</span></div><div className="text-xs text-slate-500 truncate">{bus.operator?.name} · {bus.currentLocation || 'No camera sighting yet'}</div></div><div className="text-right"><Status value={bus.complianceStatus} /><div className="text-[10px] text-slate-400 mt-1">through {bus.paidThrough ? new Date(bus.paidThrough).toLocaleDateString() : 'not paid'}</div></div></div>)}</div>}
      </Panel>
      <div className="space-y-5"><Panel title="Revenue split" subtitle="Verified payments only"><MoneyRow label="Gross collected" value={m.grossCollected} /><MoneyRow label="Government accrued" value={m.governmentAccrued} /><MoneyRow label="Kobe revenue" value={m.kobeRevenue} /><MoneyRow label="Government outstanding" value={m.governmentOutstanding} strong /></Panel><Panel title="Latest enforcement" subtitle="Historical alerts remain after resolution">{data.recentAlerts.length ? <div className="space-y-2">{data.recentAlerts.slice(0, 5).map((alert) => <div key={alert.id} className="rounded-xl border border-rose-100 bg-rose-50 p-3"><div className="flex justify-between gap-2"><span className="text-[10px] font-black text-rose-700">{alert.status}</span><span className="text-[10px] text-slate-400">{date(alert.createdAt)}</span></div><p className="text-xs text-slate-700 mt-1">{alert.message}</p></div>)}</div> : <Empty title="No enforcement alerts" body="High-confidence overdue detections will appear here." />}</Panel></div>
    </div>
  </div>;
}

function Fleet({ data, reload }: { data: Dashboard; reload: () => Promise<void> }) {
  const [operators, setOperators] = useState(data.operators);
  const [routes, setRoutes] = useState<RouteRow[]>([]);
  const [trips, setTrips] = useState<Trip[]>([]);
  const [mode, setMode] = useState<'operator' | 'bus' | 'route' | 'trip' | null>(null);
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  useEffect(() => { void Promise.all([api<RouteRow[]>('/transit/routes'), api<Trip[]>('/transit/trips')]).then(([r, t]) => { setRoutes(Array.isArray(r) ? r : []); setTrips(Array.isArray(t) ? t : []); }); }, []);
  const [operator, setOperator] = useState({ name: '', registrationNumber: '', phone: '', region: '' });
  const [bus, setBus] = useState({ operatorId: data.operators[0]?.id || '', plateNumber: '', name: '', defaultOrigin: '', defaultDestination: '', conductorName: '', conductorPhone: '', capacity: '45', routeId: '' });
  const [route, setRoute] = useState({ code: '', name: '', origin: '', destination: '', region: '', typicalMinutes: '180' });
  const [trip, setTrip] = useState({ busId: data.buses[0]?.id || '', routeId: '', origin: '', destination: '', scheduledDeparture: '', scheduledArrival: '', gate: '' });
  const submit = async (kind: NonNullable<typeof mode>) => {
    setBusy(true); setError('');
    try {
      if (kind === 'operator') { await api('/transit/operators', { method: 'POST', body: JSON.stringify(operator) }); setOperator({ name: '', registrationNumber: '', phone: '', region: '' }); }
      if (kind === 'bus') await api('/transit/buses', { method: 'POST', body: JSON.stringify({ ...bus, capacity: Number(bus.capacity), routeId: bus.routeId || undefined }) });
      if (kind === 'route') await api('/transit/routes', { method: 'POST', body: JSON.stringify({ ...route, typicalMinutes: Number(route.typicalMinutes) }) });
      if (kind === 'trip') await api('/transit/trips', { method: 'POST', body: JSON.stringify({ ...trip, routeId: trip.routeId || undefined, scheduledDeparture: new Date(trip.scheduledDeparture).toISOString(), scheduledArrival: trip.scheduledArrival ? new Date(trip.scheduledArrival).toISOString() : undefined }) });
      setMode(null); await reload();
      const [o, r, t] = await Promise.all([api<Operator[]>('/transit/operators'), api<RouteRow[]>('/transit/routes'), api<Trip[]>('/transit/trips')]); setOperators(o); setRoutes(r); setTrips(t);
    } catch (cause) { setError((cause as Error).message); } finally { setBusy(false); }
  };
  return <div className="space-y-5">
    <PageHead title="Fleet and trip operations" subtitle="The bus identity is permanent. Plates, operators and trips retain their history." actions={<div className="flex flex-wrap gap-2"><Action onClick={() => setMode('operator')}><Plus /> Operator</Action><Action onClick={() => setMode('bus')} primary><Plus /> Bus</Action><Action onClick={() => setMode('route')}><Plus /> Route</Action><Action onClick={() => setMode('trip')}><Plus /> Trip</Action></div>} />
    {error && <Notice tone="error">{error}</Notice>}
    {mode && <Modal title={`Add ${mode}`} close={() => setMode(null)}>{mode === 'operator' && <FormGrid><Field label="Operator name"><Input value={operator.name} onChange={(v) => setOperator({ ...operator, name: v })} /></Field><Field label="Registration no."><Input value={operator.registrationNumber} onChange={(v) => setOperator({ ...operator, registrationNumber: v })} /></Field><Field label="Phone"><Input value={operator.phone} onChange={(v) => setOperator({ ...operator, phone: v })} /></Field><Field label="Region"><Input value={operator.region} onChange={(v) => setOperator({ ...operator, region: v })} /></Field></FormGrid>}{mode === 'bus' && <FormGrid><Field label="Operator"><Select value={bus.operatorId} onChange={(v) => setBus({ ...bus, operatorId: v })} options={operators.map((o) => [o.id, o.name])} /></Field><Field label="License plate"><Input value={bus.plateNumber} onChange={(v) => setBus({ ...bus, plateNumber: v.toUpperCase() })} placeholder="T 123 ABC" /></Field><Field label="Bus name"><Input value={bus.name} onChange={(v) => setBus({ ...bus, name: v })} /></Field><Field label="Route"><Select value={bus.routeId} onChange={(v) => setBus({ ...bus, routeId: v })} options={[['', 'No default route'], ...routes.map((r) => [r.id, `${r.origin} → ${r.destination}`])]} /></Field><Field label="Default origin"><Input value={bus.defaultOrigin} onChange={(v) => setBus({ ...bus, defaultOrigin: v })} /></Field><Field label="Default destination"><Input value={bus.defaultDestination} onChange={(v) => setBus({ ...bus, defaultDestination: v })} /></Field><Field label="Conductor"><Input value={bus.conductorName} onChange={(v) => setBus({ ...bus, conductorName: v })} /></Field><Field label="Conductor phone"><Input value={bus.conductorPhone} onChange={(v) => setBus({ ...bus, conductorPhone: v })} /></Field><Field label="Capacity"><Input type="number" value={bus.capacity} onChange={(v) => setBus({ ...bus, capacity: v })} /></Field></FormGrid>}{mode === 'route' && <FormGrid><Field label="Route code"><Input value={route.code} onChange={(v) => setRoute({ ...route, code: v.toUpperCase() })} /></Field><Field label="Name"><Input value={route.name} onChange={(v) => setRoute({ ...route, name: v })} /></Field><Field label="Origin"><Input value={route.origin} onChange={(v) => setRoute({ ...route, origin: v })} /></Field><Field label="Destination"><Input value={route.destination} onChange={(v) => setRoute({ ...route, destination: v })} /></Field><Field label="Region"><Input value={route.region} onChange={(v) => setRoute({ ...route, region: v })} /></Field><Field label="Typical minutes"><Input type="number" value={route.typicalMinutes} onChange={(v) => setRoute({ ...route, typicalMinutes: v })} /></Field></FormGrid>}{mode === 'trip' && <FormGrid><Field label="Bus"><Select value={trip.busId} onChange={(v) => setTrip({ ...trip, busId: v })} options={data.buses.map((b) => [b.id, `${b.plate?.plateNumber} · ${b.name}`])} /></Field><Field label="Route"><Select value={trip.routeId} onChange={(v) => { const r = routes.find((x) => x.id === v); setTrip({ ...trip, routeId: v, origin: r?.origin ?? trip.origin, destination: r?.destination ?? trip.destination }); }} options={[['', 'Select route'], ...routes.map((r) => [r.id, r.name])]} /></Field><Field label="Origin"><Input value={trip.origin} onChange={(v) => setTrip({ ...trip, origin: v })} /></Field><Field label="Destination"><Input value={trip.destination} onChange={(v) => setTrip({ ...trip, destination: v })} /></Field><Field label="Scheduled departure"><Input type="datetime-local" value={trip.scheduledDeparture} onChange={(v) => setTrip({ ...trip, scheduledDeparture: v })} /></Field><Field label="Scheduled arrival"><Input type="datetime-local" value={trip.scheduledArrival} onChange={(v) => setTrip({ ...trip, scheduledArrival: v })} /></Field><Field label="Gate"><Input value={trip.gate} onChange={(v) => setTrip({ ...trip, gate: v })} /></Field></FormGrid>}<button onClick={() => void submit(mode)} disabled={busy} className="mt-5 w-full h-11 rounded-xl bg-cyan-600 text-white font-black disabled:opacity-50">{busy ? 'Saving…' : `Save ${mode}`}</button></Modal>}
    <div className="grid xl:grid-cols-2 gap-5"><Panel title="Registered fleet" subtitle={`${data.buses.length} permanent vehicle records`}>{data.buses.length ? <div className="divide-y divide-slate-100">{data.buses.map((row) => <div key={row.id} className="py-3 flex items-center gap-3"><div className="h-10 w-10 rounded-xl bg-cyan-50 text-cyan-700 grid place-items-center"><BusFront className="h-5 w-5" /></div><div className="flex-1 min-w-0"><b className="block truncate">{row.name}</b><span className="text-xs text-slate-500">{row.plate?.plateNumber} · {row.operator?.name}</span></div><Status value={row.complianceStatus} /></div>)}</div> : <Empty title="No buses" body="Create an operator, then register the first bus and plate." />}</Panel><Panel title="Trips and Transit Board" subtitle="Latest scheduled journeys">{trips.length ? <div className="space-y-2">{trips.slice(0, 12).map((row) => <div key={row.id} className="rounded-xl border border-slate-200 p-3 flex items-center gap-3"><div className="h-9 w-9 rounded-lg bg-slate-100 grid place-items-center"><Route className="h-4 w-4" /></div><div className="flex-1 min-w-0"><b className="text-sm block truncate">{row.origin} → {row.destination}</b><span className="text-xs text-slate-500">{date(row.scheduledDeparture)} · {row.currentCheckpoint || 'Not departed'}</span></div><span className="text-[10px] font-black text-cyan-700">{row.status}</span></div>)}</div> : <Empty title="No trips" body="Create a route and schedule the first journey." />}</Panel></div>
  </div>;
}

function Payments({ data, reload }: { data: Dashboard; reload: () => Promise<void> }) {
  const [operatorId, setOperatorId] = useState(data.operators[0]?.id || '');
  const operatorBuses = data.buses.filter((b) => b.operatorId === operatorId);
  const [selected, setSelected] = useState<string[]>([]);
  const [method, setMethod] = useState('MOBILE_MONEY'); const [externalReference, setExternalReference] = useState(''); const [verificationReference, setVerificationReference] = useState('');
  const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [receipt, setReceipt] = useState<Payment | null>(null);
  useEffect(() => { setSelected([]); }, [operatorId]);
  const total = Number(data.policy.feeAmount) * selected.length;
  const submit = async () => { setBusy(true); setError(''); try { const result = await api<{ payment: Payment }>('/transit/payments/verify', { method: 'POST', body: JSON.stringify({ operatorId, busIds: selected, amount: total, method, externalReference, verificationReference, idempotencyKey: crypto.randomUUID() }) }); setReceipt(result.payment); await reload(); } catch (cause) { setError((cause as Error).message); } finally { setBusy(false); } };
  return <div className="space-y-5"><PageHead title="Weekly plate fee" subtitle="Only verified payments update compliance. Fleet payments allocate one complete period to every selected plate." />{error && <Notice tone="error">{error}</Notice>}{receipt && <Notice tone="success"><b>Payment verified:</b> {receipt.paymentReference} · receipt {receipt.receiptNumber}</Notice>}<div className="grid xl:grid-cols-[.8fr_1.2fr] gap-5"><Panel title="Verified payment" subtitle={`${money(data.policy.feeAmount, data.policy.currency)} per bus every ${data.policy.periodDays} days`}><div className="space-y-4"><Field label="Operator"><Select value={operatorId} onChange={setOperatorId} options={data.operators.map((o) => [o.id, o.name])} /></Field><div><div className="flex items-center justify-between mb-2"><label className="text-xs font-bold text-slate-600">Plates</label><button onClick={() => setSelected(selected.length === operatorBuses.length ? [] : operatorBuses.map((b) => b.id))} className="text-xs font-bold text-cyan-700">{selected.length === operatorBuses.length ? 'Clear' : 'Select all'}</button></div><div className="max-h-56 overflow-auto rounded-xl border border-slate-200 divide-y divide-slate-100">{operatorBuses.map((bus) => <label key={bus.id} className="p-3 flex items-center gap-3 cursor-pointer hover:bg-slate-50"><input type="checkbox" checked={selected.includes(bus.id)} onChange={() => setSelected((s) => s.includes(bus.id) ? s.filter((id) => id !== bus.id) : [...s, bus.id])} className="h-4 w-4 accent-cyan-600" /><span className="flex-1 text-sm font-bold">{bus.plate?.plateNumber} <small className="font-normal text-slate-500">· {bus.name}</small></span><Status value={bus.complianceStatus} /></label>)}{!operatorBuses.length && <Empty title="No buses for operator" body="Register buses in Fleet & Trips first." />}</div></div><Field label="Payment rail"><Select value={method} onChange={setMethod} options={['MOBILE_MONEY', 'BANK', 'KOBEPAY', 'OTHER'].map((v) => [v, v.replace('_', ' ')])} /></Field><Field label="Provider transaction ID"><Input value={externalReference} onChange={setExternalReference} placeholder="Unique mobile-money or bank reference" /></Field><Field label="Verification reference"><Input value={verificationReference} onChange={setVerificationReference} placeholder="Gateway/listener verification reference" /></Field><div className="rounded-2xl bg-[#081b31] text-white p-4 flex justify-between items-end"><div><div className="text-[10px] text-white/55 uppercase tracking-wider">Total verified allocation</div><div className="text-2xl font-black mt-1">{money(total, data.policy.currency)}</div></div><div className="text-right text-xs text-white/60">{selected.length} plate{selected.length === 1 ? '' : 's'}<br />50/50 per current policy</div></div><button onClick={() => void submit()} disabled={busy || !selected.length || !externalReference || !verificationReference} className="w-full h-12 rounded-xl bg-cyan-600 text-white font-black disabled:opacity-40 inline-flex items-center justify-center gap-2">{busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <BadgeCheck className="h-4 w-4" />} Verify and allocate payment</button></div></Panel><Panel title="Recent verified payments" subtitle="Each row has an immutable receipt and per-plate allocations">{data.recentPayments.length ? <div className="space-y-2">{data.recentPayments.map((row) => <div key={row.id} className="rounded-xl border border-slate-200 p-3 flex items-center gap-3"><div className="h-10 w-10 rounded-xl bg-emerald-50 text-emerald-700 grid place-items-center"><Banknote className="h-5 w-5" /></div><div className="min-w-0 flex-1"><b className="text-sm block truncate">{row.paymentReference}</b><span className="text-xs text-slate-500">{row.busCount} plate{row.busCount === 1 ? '' : 's'} · {row.method} · {date(row.createdAt)}</span></div><b className="text-sm">{money(row.amount, data.policy.currency)}</b></div>)}</div> : <Empty title="No payments yet" body="A verified single-bus or fleet payment will appear here." />}</Panel></div></div>;
}

function Anpr({ data, reload }: { data: Dashboard; reload: () => Promise<void> }) {
  const [cameras, setCameras] = useState<CameraRow[]>([]); const [detections, setDetections] = useState<Detection[]>(data.recentDetections);
  const [showCamera, setShowCamera] = useState(false); const [camera, setCamera] = useState({ code: '', name: '', location: '', direction: 'BOTH', confidenceThreshold: '0.85' });
  const [scan, setScan] = useState({ cameraId: '', plateNumber: '', confidence: '0.96', direction: 'EXIT', imageUrl: '' });
  const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [result, setResult] = useState('');
  const load = useCallback(async () => { const [c, d] = await Promise.all([api<CameraRow[]>('/transit/cameras'), api<Detection[]>('/transit/detections')]); setCameras(c); setDetections(d); setScan((s) => ({ ...s, cameraId: s.cameraId || c[0]?.id || '' })); }, []);
  useEffect(() => { void load(); }, [load]);
  const saveCamera = async () => { setBusy(true); setError(''); try { await api('/transit/cameras', { method: 'POST', body: JSON.stringify({ ...camera, confidenceThreshold: Number(camera.confidenceThreshold) }) }); setShowCamera(false); await load(); } catch (cause) { setError((cause as Error).message); } finally { setBusy(false); } };
  const submit = async () => { setBusy(true); setError(''); try { const r = await api<{ action: string }>('/transit/detections', { method: 'POST', body: JSON.stringify({ ...scan, confidence: Number(scan.confidence), imageUrl: scan.imageUrl || undefined }) }); setResult(r.action); await Promise.all([load(), reload()]); } catch (cause) { setError((cause as Error).message); } finally { setBusy(false); } };
  return <div className="space-y-5"><PageHead title="ANPR compliance gateway" subtitle="Every valid scan updates tracking and checks the current plate fee. Low confidence always pauses for review." actions={<Action onClick={() => setShowCamera(true)}><Plus /> Camera</Action>} />{error && <Notice tone="error">{error}</Notice>}{result && <Notice tone={result === 'OVERDUE_ALERT' ? 'error' : result === 'MANUAL_REVIEW' ? 'warning' : 'success'}>Detection result: <b>{result.replace('_', ' ')}</b></Notice>}{showCamera && <Modal title="Add ANPR camera" close={() => setShowCamera(false)}><FormGrid><Field label="Camera code"><Input value={camera.code} onChange={(v) => setCamera({ ...camera, code: v.toUpperCase() })} /></Field><Field label="Name"><Input value={camera.name} onChange={(v) => setCamera({ ...camera, name: v })} /></Field><Field label="Location"><Input value={camera.location} onChange={(v) => setCamera({ ...camera, location: v })} /></Field><Field label="Direction"><Select value={camera.direction} onChange={(v) => setCamera({ ...camera, direction: v })} options={['ENTRY', 'EXIT', 'BOTH'].map((v) => [v, v])} /></Field><Field label="Automatic threshold"><Input type="number" value={camera.confidenceThreshold} onChange={(v) => setCamera({ ...camera, confidenceThreshold: v })} /></Field></FormGrid><button onClick={() => void saveCamera()} disabled={busy} className="mt-5 w-full h-11 rounded-xl bg-cyan-600 text-white font-black">Save camera</button></Modal>}<div className="grid xl:grid-cols-[.75fr_1.25fr] gap-5"><Panel title="Ingest camera detection" subtitle="Use this form to test the same endpoint an approved camera gateway calls"><div className="space-y-4"><Field label="Camera"><Select value={scan.cameraId} onChange={(v) => setScan({ ...scan, cameraId: v })} options={cameras.map((c) => [c.id, `${c.code} · ${c.location || c.name}`])} /></Field><Field label="Observed plate"><Input value={scan.plateNumber} onChange={(v) => setScan({ ...scan, plateNumber: v.toUpperCase() })} placeholder="T 123 ABC" /></Field><div className="grid grid-cols-2 gap-3"><Field label="Confidence (0–1)"><Input type="number" value={scan.confidence} onChange={(v) => setScan({ ...scan, confidence: v })} /></Field><Field label="Direction"><Select value={scan.direction} onChange={(v) => setScan({ ...scan, direction: v })} options={['ENTRY', 'EXIT', 'BOTH'].map((v) => [v, v])} /></Field></div><Field label="Evidence image URL (optional)"><Input value={scan.imageUrl} onChange={(v) => setScan({ ...scan, imageUrl: v })} /></Field><button onClick={() => void submit()} disabled={busy || !scan.cameraId || !scan.plateNumber} className="w-full h-12 rounded-xl bg-[#081b31] text-white font-black disabled:opacity-40 inline-flex items-center justify-center gap-2"><ScanLine className="h-5 w-5" /> Process detection</button><p className="text-[11px] leading-5 text-slate-500">This creates compliance alerts only. Fines, seizure, suspension and police actions require separately authorized government rules.</p></div></Panel><Panel title="Detection stream" subtitle={`${detections.filter((d) => d.reviewStatus === 'MANUAL_REVIEW').length} waiting for manual review`}>{detections.length ? <div className="space-y-2">{detections.slice(0, 30).map((row) => <div key={row.id} className={`rounded-xl border p-3 flex gap-3 ${row.reviewStatus === 'MANUAL_REVIEW' ? 'border-amber-200 bg-amber-50' : row.complianceStatus === 'OVERDUE' ? 'border-rose-200 bg-rose-50' : 'border-slate-200 bg-white'}`}><div className="h-10 w-10 rounded-xl bg-white border border-slate-200 grid place-items-center"><Camera className="h-5 w-5" /></div><div className="flex-1 min-w-0"><div className="flex items-center gap-2"><b className="font-mono">{row.observedPlate}</b><span className="text-[10px] text-slate-500">{Math.round(Number(row.confidence) * 100)}%</span></div><div className="text-xs text-slate-500 mt-0.5">{row.direction} · {date(row.detectedAt)}</div></div><div className="text-right"><span className="text-[10px] font-black text-slate-700">{row.reviewStatus.replace('_', ' ')}</span>{row.complianceStatus && <div className="mt-1"><Status value={row.complianceStatus as Compliance} /></div>}</div></div>)}</div> : <Empty title="No detections" body="Connect a camera or submit a test detection." />}</Panel></div></div>;
}

function Government({ data, reload }: { data: Dashboard; reload: () => Promise<void> }) {
  const [policyOpen, setPolicyOpen] = useState(false); const [settlementOpen, setSettlementOpen] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const [policy, setPolicy] = useState({ feeAmount: String(data.policy.feeAmount), currency: data.policy.currency, periodDays: String(data.policy.periodDays), graceDays: String(data.policy.graceDays), dueSoonDays: String(data.policy.dueSoonDays), governmentPercent: String(data.policy.governmentPercent), kobePercent: String(data.policy.kobePercent), automaticAnprThreshold: String(data.policy.automaticAnprThreshold) });
  const monthStart = new Date(); monthStart.setDate(1); monthStart.setHours(0, 0, 0, 0);
  const [period, setPeriod] = useState({ periodStart: monthStart.toISOString().slice(0, 10), periodEnd: new Date().toISOString().slice(0, 10) });
  const savePolicy = async () => { setBusy(true); setError(''); try { await api('/transit/policy', { method: 'POST', body: JSON.stringify(Object.fromEntries(Object.entries(policy).map(([k, v]) => [k, ['currency'].includes(k) ? v : Number(v)]))) }); setPolicyOpen(false); await reload(); } catch (cause) { setError((cause as Error).message); } finally { setBusy(false); } };
  const createSettlement = async () => { setBusy(true); setError(''); try { await api('/transit/government/settlements', { method: 'POST', body: JSON.stringify({ periodStart: new Date(`${period.periodStart}T00:00:00`).toISOString(), periodEnd: new Date(`${period.periodEnd}T23:59:59`).toISOString() }) }); setSettlementOpen(false); await reload(); } catch (cause) { setError((cause as Error).message); } finally { setBusy(false); } };
  const settle = async (row: Settlement) => { const ref = window.prompt('Government transfer/payment reference'); if (!ref) return; setBusy(true); try { await api(`/transit/government/settlements/${row.id}/settle`, { method: 'POST', body: JSON.stringify({ paymentReference: ref }) }); await reload(); } catch (cause) { setError((cause as Error).message); } finally { setBusy(false); } };
  const reconcile = async (row: Settlement) => { setBusy(true); try { await api(`/transit/government/settlements/${row.id}/reconcile`, { method: 'POST', body: JSON.stringify({ note: 'Matched to government remittance reference' }) }); await reload(); } catch (cause) { setError((cause as Error).message); } finally { setBusy(false); } };
  return <div className="space-y-5"><PageHead title="Government compliance and settlement" subtitle="Owner-scoped authorized view of registered plates, collections, allocation liability and enforcement history." actions={<div className="flex gap-2"><Action onClick={() => setPolicyOpen(true)}><Settings2 /> Fee policy</Action><Action onClick={() => setSettlementOpen(true)} primary><Landmark /> New settlement</Action></div>} />{error && <Notice tone="error">{error}</Notice>}{policyOpen && <Modal title="Create new effective fee policy" close={() => setPolicyOpen(false)}><FormGrid><Field label="Fee amount"><Input type="number" value={policy.feeAmount} onChange={(v) => setPolicy({ ...policy, feeAmount: v })} /></Field><Field label="Currency"><Input value={policy.currency} onChange={(v) => setPolicy({ ...policy, currency: v.toUpperCase() })} /></Field><Field label="Period days"><Input type="number" value={policy.periodDays} onChange={(v) => setPolicy({ ...policy, periodDays: v })} /></Field><Field label="Grace days"><Input type="number" value={policy.graceDays} onChange={(v) => setPolicy({ ...policy, graceDays: v })} /></Field><Field label="Due-soon days"><Input type="number" value={policy.dueSoonDays} onChange={(v) => setPolicy({ ...policy, dueSoonDays: v })} /></Field><Field label="ANPR threshold"><Input type="number" value={policy.automaticAnprThreshold} onChange={(v) => setPolicy({ ...policy, automaticAnprThreshold: v })} /></Field><Field label="Government %"><Input type="number" value={policy.governmentPercent} onChange={(v) => setPolicy({ ...policy, governmentPercent: v, kobePercent: String(100 - Number(v)) })} /></Field><Field label="Kobe %"><Input type="number" value={policy.kobePercent} onChange={(v) => setPolicy({ ...policy, kobePercent: v, governmentPercent: String(100 - Number(v)) })} /></Field></FormGrid><button onClick={() => void savePolicy()} disabled={busy} className="mt-5 w-full h-11 rounded-xl bg-cyan-600 text-white font-black">Activate new policy</button></Modal>}{settlementOpen && <Modal title="Create government settlement batch" close={() => setSettlementOpen(false)}><FormGrid><Field label="From"><Input type="date" value={period.periodStart} onChange={(v) => setPeriod({ ...period, periodStart: v })} /></Field><Field label="To"><Input type="date" value={period.periodEnd} onChange={(v) => setPeriod({ ...period, periodEnd: v })} /></Field></FormGrid><p className="text-xs text-slate-500 mt-3">Only accrued, unsettled allocation rows in this period are included.</p><button onClick={() => void createSettlement()} disabled={busy} className="mt-5 w-full h-11 rounded-xl bg-cyan-600 text-white font-black">Create settlement ledger</button></Modal>}<div className="grid grid-cols-2 lg:grid-cols-4 gap-3"><Metric label="Gross fees" value={money(data.metrics.grossCollected)} icon={<CircleDollarSign />} /><Metric label="Government share" value={money(data.metrics.governmentAccrued)} tone="green" icon={<Landmark />} /><Metric label="Kobe share" value={money(data.metrics.kobeRevenue)} icon={<WalletCards />} /><Metric label="Outstanding payable" value={money(data.metrics.governmentOutstanding)} tone="amber" icon={<AlertTriangle />} /></div><div className="grid xl:grid-cols-[1.2fr_.8fr] gap-5"><Panel title="Government settlement ledger" subtitle="Accrued → pending → settled → reconciled">{data.settlements.length ? <div className="space-y-2">{data.settlements.map((row) => <div key={row.id} className="rounded-xl border border-slate-200 p-3"><div className="flex flex-wrap items-center justify-between gap-2"><div><b className="text-sm">{row.settlementReference}</b><div className="text-xs text-slate-500">{new Date(row.periodStart).toLocaleDateString()} – {new Date(row.periodEnd).toLocaleDateString()}</div></div><div className="text-right"><b className="text-sm">{money(row.governmentAmount)}</b><div className="text-[10px] font-black text-cyan-700">{row.status}</div></div></div>{row.status === 'PENDING' && <button onClick={() => void settle(row)} disabled={busy} className="mt-3 h-8 px-3 rounded-lg bg-[#081b31] text-white text-xs font-bold">Record government transfer</button>}{row.status === 'SETTLED' && <button onClick={() => void reconcile(row)} disabled={busy} className="mt-3 h-8 px-3 rounded-lg bg-emerald-600 text-white text-xs font-bold">Reconcile</button>}{row.paymentReference && <div className="mt-2 text-[11px] text-slate-500">Payment ref: {row.paymentReference}</div>}</div>)}</div> : <Empty title="No settlement batches" body="Create a batch after verified payments accrue government share." />}</Panel><Panel title="Compliance totals" subtitle="Current plate state"><ComplianceBar label="Paid" count={data.metrics.paid} total={data.metrics.registeredBuses} color="bg-emerald-500" /><ComplianceBar label="Due soon" count={data.metrics.dueSoon} total={data.metrics.registeredBuses} color="bg-amber-400" /><ComplianceBar label="Grace period" count={data.metrics.gracePeriod} total={data.metrics.registeredBuses} color="bg-orange-500" /><ComplianceBar label="Overdue" count={data.metrics.overdue} total={data.metrics.registeredBuses} color="bg-rose-500" /><ComplianceBar label="Exempt" count={data.metrics.exempt} total={data.metrics.registeredBuses} color="bg-blue-500" /></Panel></div></div>;
}

function Cases({ data, reload }: { data: Dashboard; reload: () => Promise<void> }) {
  const [kind, setKind] = useState<'exemption' | 'dispute'>('exemption'); const [rows, setRows] = useState<CaseRow[]>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const [form, setForm] = useState({ busId: data.buses[0]?.id || '', exemptionType: '', authority: '', reason: '', effectiveAt: '', expiresAt: '', transactionId: '', amount: '', paymentProvider: '', paymentDate: '', explanation: '' });
  const load = useCallback(async () => { const r = await api<CaseRow[]>(`/transit/${kind === 'exemption' ? 'exemptions' : 'disputes'}`); setRows(Array.isArray(r) ? r : []); }, [kind]); useEffect(() => { void load(); }, [load]);
  const submit = async () => { setBusy(true); setError(''); try { const body = kind === 'exemption' ? { busId: form.busId, exemptionType: form.exemptionType, authority: form.authority, reason: form.reason, effectiveAt: new Date(form.effectiveAt).toISOString(), expiresAt: new Date(form.expiresAt).toISOString() } : { busId: form.busId, transactionId: form.transactionId, amount: Number(form.amount), paymentProvider: form.paymentProvider, paymentDate: new Date(form.paymentDate).toISOString(), explanation: form.explanation }; await api(`/transit/${kind === 'exemption' ? 'exemptions' : 'disputes'}`, { method: 'POST', body: JSON.stringify(body) }); await Promise.all([load(), reload()]); } catch (cause) { setError((cause as Error).message); } finally { setBusy(false); } };
  return <div className="space-y-5"><PageHead title="Exemptions and payment disputes" subtitle="Neither case changes compliance automatically. Exemptions require approval; disputes retain the submitted evidence." />{error && <Notice tone="error">{error}</Notice>}<div className="inline-flex rounded-xl border border-slate-200 bg-white p-1"><button onClick={() => setKind('exemption')} className={`h-9 px-4 rounded-lg text-xs font-bold ${kind === 'exemption' ? 'bg-[#081b31] text-white' : 'text-slate-500'}`}>Exemptions</button><button onClick={() => setKind('dispute')} className={`h-9 px-4 rounded-lg text-xs font-bold ${kind === 'dispute' ? 'bg-[#081b31] text-white' : 'text-slate-500'}`}>Payment disputes</button></div><div className="grid xl:grid-cols-[.8fr_1.2fr] gap-5"><Panel title={kind === 'exemption' ? 'Request official exemption' : 'Submit payment dispute'} subtitle="Evidence and approvals remain in the audit record"><div className="space-y-3"><Field label="Bus / plate"><Select value={form.busId} onChange={(v) => setForm({ ...form, busId: v })} options={data.buses.map((b) => [b.id, `${b.plate?.plateNumber} · ${b.name}`])} /></Field>{kind === 'exemption' ? <><Field label="Exemption type"><Input value={form.exemptionType} onChange={(v) => setForm({ ...form, exemptionType: v })} /></Field><Field label="Authorizing authority"><Input value={form.authority} onChange={(v) => setForm({ ...form, authority: v })} /></Field><Field label="Reason"><Input value={form.reason} onChange={(v) => setForm({ ...form, reason: v })} /></Field><div className="grid grid-cols-2 gap-3"><Field label="Effective"><Input type="date" value={form.effectiveAt} onChange={(v) => setForm({ ...form, effectiveAt: v })} /></Field><Field label="Expires"><Input type="date" value={form.expiresAt} onChange={(v) => setForm({ ...form, expiresAt: v })} /></Field></div></> : <><Field label="Transaction ID"><Input value={form.transactionId} onChange={(v) => setForm({ ...form, transactionId: v })} /></Field><div className="grid grid-cols-2 gap-3"><Field label="Amount"><Input type="number" value={form.amount} onChange={(v) => setForm({ ...form, amount: v })} /></Field><Field label="Provider"><Input value={form.paymentProvider} onChange={(v) => setForm({ ...form, paymentProvider: v })} /></Field></div><Field label="Payment date"><Input type="date" value={form.paymentDate} onChange={(v) => setForm({ ...form, paymentDate: v })} /></Field><Field label="Explanation"><Input value={form.explanation} onChange={(v) => setForm({ ...form, explanation: v })} /></Field></>}<button onClick={() => void submit()} disabled={busy || !form.busId} className="w-full h-11 rounded-xl bg-cyan-600 text-white font-black disabled:opacity-40">Submit {kind}</button></div></Panel><Panel title="Case history" subtitle={`${rows.length} retained record${rows.length === 1 ? '' : 's'}`}>{rows.length ? <div className="space-y-2">{rows.map((row) => { const bus = data.buses.find((b) => b.id === row.busId); return <div key={row.id} className="rounded-xl border border-slate-200 p-3 flex gap-3"><div className="h-10 w-10 rounded-xl bg-amber-50 text-amber-700 grid place-items-center"><FileWarning className="h-5 w-5" /></div><div className="flex-1"><b className="text-sm">{bus?.plate?.plateNumber || 'Bus'} · {row.status}</b><p className="text-xs text-slate-500 mt-1">{row.reason || row.explanation || row.authority}</p></div><span className="text-[10px] text-slate-400">{date(row.createdAt)}</span></div>; })}</div> : <Empty title="No cases" body="Submitted exemptions and disputes appear here." />}</Panel></div></div>;
}

function Metric({ label, value, sub, icon, tone = 'blue' }: { label: string; value: ReactNode; sub?: string; icon: ReactNode; tone?: 'blue' | 'green' | 'red' | 'amber' }) { const c = { blue: 'bg-cyan-50 text-cyan-700', green: 'bg-emerald-50 text-emerald-700', red: 'bg-rose-50 text-rose-700', amber: 'bg-amber-50 text-amber-700' }[tone]; return <div className="rounded-2xl bg-white border border-slate-200 p-4 flex items-start gap-3 shadow-sm"><div className={`h-10 w-10 rounded-xl grid place-items-center [&>svg]:h-5 [&>svg]:w-5 ${c}`}>{icon}</div><div className="min-w-0"><div className="text-[11px] text-slate-500 font-bold truncate">{label}</div><div className="text-xl sm:text-2xl font-black mt-0.5 truncate">{value}</div>{sub && <div className="text-[10px] text-slate-400 mt-0.5">{sub}</div>}</div></div>; }
function Panel({ title, subtitle, children }: { title: string; subtitle?: string; children: ReactNode }) { return <section className="rounded-2xl bg-white border border-slate-200 shadow-sm overflow-hidden"><div className="px-4 sm:px-5 py-4 border-b border-slate-100"><h3 className="text-sm font-black">{title}</h3>{subtitle && <p className="text-[11px] text-slate-500 mt-0.5">{subtitle}</p>}</div><div className="p-4 sm:p-5">{children}</div></section>; }
function PageHead({ title, subtitle, actions }: { title: string; subtitle: string; actions?: ReactNode }) { return <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-3"><div><h2 className="text-xl sm:text-2xl font-black tracking-tight">{title}</h2><p className="text-xs sm:text-sm text-slate-500 mt-1 max-w-3xl">{subtitle}</p></div>{actions}</div>; }
function Action({ children, onClick, primary = false }: { children: ReactNode; onClick: () => void; primary?: boolean }) { return <button onClick={onClick} className={`h-9 px-3 rounded-xl inline-flex items-center gap-1.5 text-xs font-black [&>svg]:h-4 [&>svg]:w-4 ${primary ? 'bg-cyan-600 text-white' : 'bg-white border border-slate-200 text-slate-700'}`}>{children}</button>; }
function Status({ value }: { value: Compliance }) { const cls: Record<Compliance, string> = { PAID: 'bg-emerald-100 text-emerald-800', DUE_SOON: 'bg-amber-100 text-amber-800', GRACE_PERIOD: 'bg-orange-100 text-orange-800', OVERDUE: 'bg-rose-100 text-rose-800', EXEMPT: 'bg-blue-100 text-blue-800', SUSPENDED: 'bg-slate-200 text-slate-700' }; return <span className={`inline-flex rounded-full px-2 py-1 text-[9px] font-black whitespace-nowrap ${cls[value] || cls.SUSPENDED}`}>{String(value).replace('_', ' ')}</span>; }
function MoneyRow({ label, value, strong }: { label: string; value: number; strong?: boolean }) { return <div className={`py-2.5 flex justify-between gap-4 text-sm border-b border-slate-100 last:border-0 ${strong ? 'font-black' : ''}`}><span className="text-slate-500">{label}</span><span>{money(value)}</span></div>; }
function ComplianceBar({ label, count, total, color }: { label: string; count: number; total: number; color: string }) { const pct = total ? Math.round(count / total * 100) : 0; return <div className="mb-4 last:mb-0"><div className="flex justify-between text-xs mb-1.5"><span className="font-bold">{label}</span><span className="text-slate-500">{count} · {pct}%</span></div><div className="h-2 rounded-full bg-slate-100 overflow-hidden"><div className={`h-full rounded-full ${color}`} style={{ width: `${pct}%` }} /></div></div>; }
function Empty({ title, body }: { title: string; body: string }) { return <div className="py-8 px-4 text-center"><div className="h-10 w-10 mx-auto rounded-xl bg-slate-100 grid place-items-center"><Search className="h-4 w-4 text-slate-400" /></div><b className="text-sm block mt-3">{title}</b><p className="text-xs text-slate-500 mt-1">{body}</p></div>; }
function Notice({ children, tone }: { children: ReactNode; tone: 'error' | 'success' | 'warning' }) { const c = tone === 'error' ? 'bg-rose-50 border-rose-200 text-rose-800' : tone === 'success' ? 'bg-emerald-50 border-emerald-200 text-emerald-800' : 'bg-amber-50 border-amber-200 text-amber-800'; return <div className={`rounded-xl border px-4 py-3 text-sm ${c}`}>{children}</div>; }
function FormGrid({ children }: { children: ReactNode }) { return <div className="grid sm:grid-cols-2 gap-3">{children}</div>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="block"><span className="block text-[11px] font-bold text-slate-600 mb-1.5">{label}</span>{children}</label>; }
function Input({ value, onChange, type = 'text', placeholder = '' }: { value: string; onChange: (value: string) => void; type?: string; placeholder?: string }) { return <input type={type} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} className="w-full h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm outline-none focus:border-cyan-500 focus:ring-2 focus:ring-cyan-500/10" />; }
function Select({ value, onChange, options }: { value: string; onChange: (value: string) => void; options: string[][] }) { return <select value={value} onChange={(e) => onChange(e.target.value)} className="w-full h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm outline-none focus:border-cyan-500"><option value="" disabled>Select…</option>{options.map(([v, l]) => <option key={v || l} value={v}>{l}</option>)}</select>; }
function Modal({ title, close, children }: { title: string; close: () => void; children: ReactNode }) { return <div className="fixed inset-0 z-[100] bg-slate-950/55 backdrop-blur-sm p-3 grid place-items-center" onMouseDown={(e) => { if (e.target === e.currentTarget) close(); }}><div className="w-full max-w-2xl max-h-[88vh] overflow-y-auto rounded-2xl bg-white shadow-2xl"><div className="sticky top-0 bg-white px-5 h-14 border-b border-slate-100 flex items-center justify-between z-10"><b>{title}</b><button onClick={close} className="h-8 w-8 rounded-lg bg-slate-100 grid place-items-center"><X className="h-4 w-4" /></button></div><div className="p-5">{children}</div></div></div>; }
function Loading() { return <div className="h-full grid place-items-center"><div className="text-center"><Loader2 className="h-8 w-8 animate-spin text-cyan-600 mx-auto" /><p className="text-sm text-slate-500 mt-3">Loading Transit ledger…</p></div></div>; }
function ErrorState({ message, retry }: { message: string; retry: () => Promise<void> }) { return <div className="h-full grid place-items-center p-6"><div className="max-w-md text-center"><AlertTriangle className="h-10 w-10 text-rose-500 mx-auto" /><h2 className="font-black mt-3">Transit could not load</h2><p className="text-sm text-slate-500 mt-2">{message}</p><button onClick={() => void retry()} className="mt-4 h-10 px-4 rounded-xl bg-[#081b31] text-white text-sm font-bold inline-flex items-center gap-2"><RefreshCw className="h-4 w-4" /> Try again</button></div></div>; }
